<?php
require __DIR__.'/../app/bootstrap.php';$u=require_seller();require_commerce();$order=order_record((int)param('id'),$u);if((int)$order['seller_id']!==(int)$u['id'])fail(404,'Order not found.');$err=[];
$transitions=['placed'=>['confirmed','cancelled'],'confirmed'=>['preparing','cancelled'],'preparing'=>['ready'],'ready'=>['completed'],'completed'=>[],'cancelled'=>[]];
if(post()){$next=val('status');if(!in_array($next,$transitions[$order['status']]??[],true))$err[]='That status change is not available.';else{$n=q('UPDATE orders SET status=?,updated_at=? WHERE id=? AND seller_id=? AND status=?',[$next,now(),$order['id'],$u['id'],$order['status']])->rowCount();if($n!==1)$err[]='This order changed in another session. Reload before trying again.';else{flash('Order status updated.');go('seller/order.php?id='.$order['id']);}}}
$items=all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]);$title='Order '.$order['reference'];require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><h1>Order <?=e($order['reference'])?></h1><a class="pill" href="<?=e(url('seller/orders.php'))?>">← Orders</a></div><?php errors($err); ?><div class="two-columns"><section class="panel padded"><?php render_order_summary($order,$items); ?></section><section class="panel padded"><h2>Customer details</h2><p><strong><?=e($order['customer_name'])?></strong><br><?=e($order['customer_phone'])?></p><?php if($order['note']): ?><p><strong>Note:</strong> <?=nl2br(e($order['note']))?></p><?php endif ?><h2>Update progress</h2><p class="hint">Current status: <?=e(status_label($order))?></p><div class="order-status-actions"><?php foreach($transitions[$order['status']]??[] as $next): $preview=$order;$preview['status']=$next; ?><form method="post" <?=$next==='cancelled'?'data-confirm="Cancel this order?"':''?>><?=csrf()?><input type="hidden" name="status" value="<?=e($next)?>"><button class="pill <?=$next==='cancelled'?'danger':'primary'?>"><?=$next==='completed'?($order['fulfillment']==='pickup'?'Mark as Collected':'Mark as Delivered'):e(status_label($preview))?></button></form><?php endforeach ?><?php if(!$transitions[$order['status']]): ?><p>This order is closed.</p><?php endif ?></div></section></div><?php require ROOT.'/app/workspace-end.php'; ?>
